function MoldFlaskClampWedgeMaker.completeMaking(m) local q=1.0+(MoldFlaskClampWedgeMaker.getQualityBonus()/100); if MoldFlaskClampWedgeMaker.maker then q=q+(MoldFlaskClampWedgeMaker.maker.skill/140) end; q=math.min(2.5,q); MoldFlaskClampWedgeMaker.productStock[m.productType]=(MoldFlaskClampWedgeMaker.productStock[m.productType] or 0)+m.quantity; MoldFlaskClampWedgeMaker.totalProducts=MoldFlaskClampWedgeMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MoldFlaskClampWedgeMaker.maker then MoldFlaskClampWedgeMaker.maker.itemsMade=MoldFlaskClampWedgeMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MoldFlaskClampWedgeMaker.maker.skill=math.min(100,MoldFlaskClampWedgeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Klin izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"moldflaskclampwedge.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
